CREATE TABLE IF NOT EXISTS reg_attachments ( id INTEGER PRIMARY KEY AUTOINCREMENT, collection TEXT NOT NULL CHECK (collection IN ('regProducts','formulaControl','labelChecklist','rawMaterials','kpiResults')), record_id TEXT NOT NULL, file_name TEXT NOT NULL, mime TEXT NOT NULL CHECK (mime IN ('image/jpeg','image/png','image/webp')), size INTEGER NOT NULL, sha256 TEXT NOT NULL, caption TEXT, data TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, voided_at TEXT, voided_by TEXT REFERENCES users(id), void_reason TEXT );
CREATE INDEX IF NOT EXISTS reg_attachments_record_idx ON reg_attachments(collection, record_id, voided_at);
CREATE TRIGGER IF NOT EXISTS reg_attachments_no_delete BEFORE DELETE ON reg_attachments BEGIN SELECT RAISE(ABORT, 'LOCKED: attachments cannot be deleted, void them instead'); END;
CREATE TRIGGER IF NOT EXISTS reg_attachments_frozen BEFORE UPDATE ON reg_attachments WHEN OLD.voided_at IS NOT NULL OR NEW.voided_at IS NULL OR NEW.id IS NOT OLD.id OR NEW.collection IS NOT OLD.collection OR NEW.record_id IS NOT OLD.record_id OR NEW.file_name IS NOT OLD.file_name OR NEW.mime IS NOT OLD.mime OR NEW.size IS NOT OLD.size OR NEW.sha256 IS NOT OLD.sha256 OR NEW.caption IS NOT OLD.caption OR NEW.data IS NOT OLD.data OR NEW.created_by IS NOT OLD.created_by OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT, 'LOCKED: attachment cannot be edited, void it and upload a new one'); END;
ALTER TABLE reg_attachments ADD COLUMN thumb TEXT;
DROP TRIGGER IF EXISTS reg_attachments_frozen;
CREATE TRIGGER reg_attachments_frozen BEFORE UPDATE ON reg_attachments WHEN OLD.voided_at IS NOT NULL OR NEW.id IS NOT OLD.id OR NEW.collection IS NOT OLD.collection OR NEW.record_id IS NOT OLD.record_id OR NEW.file_name IS NOT OLD.file_name OR NEW.mime IS NOT OLD.mime OR NEW.size IS NOT OLD.size OR NEW.sha256 IS NOT OLD.sha256 OR NEW.caption IS NOT OLD.caption OR NEW.data IS NOT OLD.data OR NEW.created_by IS NOT OLD.created_by OR NEW.created_at IS NOT OLD.created_at OR (OLD.thumb IS NOT NULL AND NEW.thumb IS NOT OLD.thumb) OR (NEW.voided_at IS NULL AND NOT (OLD.thumb IS NULL AND NEW.thumb IS NOT NULL)) BEGIN SELECT RAISE(ABORT, 'LOCKED: attachment cannot be edited, void it and upload a new one'); END;
